/* אייקוני מצרכים וכלים — מהפיגמה (icons / silhouette set). צבע דרך currentColor (מסכה). */
import { h, svg } from "./dom.js";
import { norm, NOT_INSIDE } from "./match.js";
import { entryOf, loadLexicon } from "./lexicon.js";

let index = null;           // { "ביצים": "beitzim", ... }
export async function loadIcons() {
  if (index) return index;
  await loadLexicon();   /* האייקון של מצרך מהמאגר בא מהשדה icon שלו */
  try { index = await (await fetch("assets/ingredients/index.json")).json(); } catch { index = {}; }
  return index;
}

/* «עגבניות גדולות ובשלות» → עגבנייה · «שן שום כתושה» → שום */
export function ingredientIcon(name) {
  if (!index) return null;
  /* מצרך מהמאגר — רק האייקון שנבחר לו (שדה icon). בלי icon = בלי אייקון, גם אם השם דומה
     («חלב קוקוס» לא מקבל את החלב, «כרוב סגול» לא את הכרובית — שחק 03.10). */
  const entry = entryOf(name);
  if (entry) return entry.icon || null;
  /* טקסט חופשי (שורות מתכון כמו «שן שום כתושה») — לפי מילים, כמו קודם */
  const raw = norm(name).split(" ");
  const words = raw.concat(raw.map((w) => w.replace(/^[ובלמה]/, "")).filter((w) => w.length >= 3));   /* «ובצל» → בצל */
  for (const [key, slug] of Object.entries(index)) {
    if (NOT_INSIDE[key]?.test(norm(name))) continue;   /* פחית גרגירי חומוס ≠ צלחת חומוס */
    if (key.includes(" ")) { if (norm(name).includes(key)) return slug; continue; }
    const stem = key.length > 4 ? key.slice(0, -1) : key;
    if (words.some((w) => w === key || (w.length >= 3 && (w.startsWith(stem) || key.startsWith(w))))) return slug;
  }
  return null;
}

export function ingIcon(name, size = 18) {
  const slug = ingredientIcon(name);
  if (!slug) return null;
  return h("span", { class: "ing-icon", "aria-hidden": "true", style: { "--icon": `url(${new URL("assets/ingredients/" + slug + ".svg", location.href)})`, width: size + "px", height: size + "px" } });
}

